    for (const h of hits) {
      console.log(`${h.session.id} turn ${h.turn}  ${h.at?.slice(0, 16) ?? ""}  ${h.session.project}`);
      console.log(`    ${h.why.join(" · ")}`);
      console.log(`    user: ${h.user}`);
      if (h.requestId)
        console.log(`    ${values["user-text"] ? "reacted to" : "first response"}: ${h.requestId}`);
    }
